  if (/Owner dashboard receives actual cashier revenue/.test(r.feature)) return { reviewed: 'HARNESS_ERROR', note: 'Incorrectly queried PAYMENT_TRANSACTION generic entity; payment/order ledgers use another model. Actual dashboard cash amount was observed; no defect established by this assertion.' };
