function performanceMatrix(records, appScoped) {
  const groups = new Map();
  for (const r of records) {
    if (normalize(r.endpoint) === '/api/v1/realtime/stream') continue;
    const group = (appScoped ? r.app + '|' : '') + r.method + '|' + normalize(r.endpoint);
    if (!groups.has(group)) groups.set(group, []); groups.get(group).push(r);
  }
  return [...groups.entries()].map(([k, list]) => {
    const parts = k.split('|'); const method = parts.at(-2), endpoint = parts.at(-1);
    const times = list.filter(r => Number.isFinite(r.ms) && !r.failure).map(r => r.ms).sort((a, b) => a - b);
    const mean = times.length ? times.reduce((a, b) => a + b, 0) / times.length : null;
    const p95 = times.length ? times[Math.max(0, Math.ceil(times.length * .95) - 1)] : null;
    const max = times.length ? times.at(-1) : null;
    const cls = p95 == null ? 'UNMEASURED' : p95 < 200 ? 'GOOD' : p95 < 500 ? 'ACCEPTABLE' : p95 < 1000 ? 'SLOW' : p95 < 2000 ? 'VERY SLOW' : 'INVESTIGATE';
    const bytes = list.filter(r => Number.isFinite(r.bytes)).map(r => r.bytes);
    return { app: appScoped ? parts[0] : 'API middleware', method, endpoint, calls: list.length, completed: times.length, meanMs: mean == null ? '' : +mean.toFixed(2), p95Ms: p95, maxMs: max, classification: cls, statusCounts: counts(list.map(r => r.status || 'FAILED')), failedRequests: list.filter(r => r.failure).length, errors4xx5xx: list.filter(r => r.status >= 400).length, meanPayloadBytes: bytes.length ? Math.round(bytes.reduce((a, b) => a + b, 0) / bytes.length) : '', maxPayloadBytes: bytes.length ? Math.max(...bytes) : '' };
  }).sort((a, b) => b.calls - a.calls);
}
